function validateHierarchyLimit(target, newLimit) {
  // "Must not pass over the direct parent" and "must not sit below a direct
  // child": only the direct neighbours constrain the value. Transitive
  // bounds already follow from theirs.
  if (target.parent !== null && newLimit > target.parent.limit) {
    throw new RangeError('limit must not exceed the direct parent limit');
  }
  for (const child of target.children) {
    if (child.limit > newLimit) {
      throw new RangeError('limit must not be below a direct child limit');
    }
  }
}

// Shrink fallout: queued requests that can never fit are refused
// immediately and leave the queue, so they never block later arrivals.
// Occupations are never torn apart; a combo that can no longer be satisfied
// is refused as a whole, releasing its reservation in the same cut. An
// owned entry may queue in another family, so both this family's queue and
// this gate's owned entries are swept; every affected family is then
// re-served so a refused head does not stop the waiters behind it.
function refuseUnfittable(newLimit) {
  const poolShrink = state.isRoot;
  const touchedRoots = new Set();
  const refuseIfOversized = (entry) => {
    let oversized;
    if (entry.combo) {
      // The whole combo must fit the pool; only the pool cap can refuse it,
      // because member slices above a member's limit are simply borrowed.
      oversized = poolShrink ? entry.totalUnits > newLimit : false;
    } else {
      // A single-gate request above its own gate limit borrows the excess
      // up the chain, so only shrinking the family pool itself can make it
      // impossible to ever satisfy.
      oversized = poolShrink && entry.units > newLimit;
    }
    if (oversized) {
      touchedRoots.add(entry.qRoot);
      settleEntryEntry(entry, 'refused');
    }
  };

  const r = state.root;
  touchedRoots.add(r);
  const q = r.queue;
  for (let i = r.head; i < q.length; i += 1) {
    const entry = q[i];
    if (!entry.removed) refuseIfOversized(entry);
  }
  // Entries owned by this gate whose queue now lives in another family.
  for (const entry of state.ownedEntries) {
    if (!entry.removed && entry.qRoot !== r) refuseIfOversized(entry);
  }
  for (const touched of touchedRoots) serveQueueRoot(touched);
}

