function enqueueEntry(r, entry) {
  entry.owner.ownedEntries.add(entry);
  if (entry.signal !== null) {
    entry.signal.addEventListener('abort', entry.onAbort, { once: true });
  }
  for (const charge of entry.waitCharges) charge.gate.waiting += charge.units;
  armEntry(entry, entry.owner.maxWaitMs);
  r.queue.push(entry);
  r.liveQueued += 1;
  // The up-front gather (if any) just ran against this exact room; stamp the
  // room version so the fairness pass below does not replan it twice.
  entry.roomVer = r.roomVer;
  // A fresh arrival may pass a blocked head combo outright: fairness is
  // evaluated immediately, not only at the next window flip.
  serveQueueRoot(r);
}

