input.old_string:
// Allocation walks arrivals in order against the current pool. A head combo
// that cannot be gathered whole does not starve later arrivals: a later
// request that fits outright passes it and the combo yields once; after
// yielding twice (cumulatively, across passes and flips) it becomes a hard
// barrier like a non-fitting single. A non-fitting single is always a hard
// barrier: it neither overtakes nor is overtaken. The room-version cache
// makes every unrelated arrival, withdrawal or flip amortized O(1) at the
// blocked head, and each pass stops as soon as the earliest blocker hardens
// (at most two overtakes after a live head).
function allocateRoot(r, countRollback) {
  const q = r.queue;
  let wave = r.serveWave; // overtakes counted so far, monotonic across passes
  let stopWave = Infinity; // earliest wave at which a blocker hardens
  let blockerCount = 0; // blocked combos registered earlier in this pass
  for (let i = r.head; i < q.length; i += 1) {
    const entry = q[i];
    if (entry.removed) continue;
    if (wave >= stopWave) break;
    if (attemptEntry(entry, r, countRollback)) {
      if (blockerCount > 0) wave += 1; // one yield per overtaken blocker
      continue;
    }
    if (!entry.combo) break; // single-gate requests are ordinary barriers
    // Blocked combo: register a soft barrier and remember where it hardened.
    if (entry.blockG !== -1) entry.yields += wave - entry.blockG;
    entry.blockG = wave;
    const hardensAt = wave + (2 - entry.yields);
    blockerCount += 1;
    if (hardensAt < stopWave) stopWave = hardensAt;
  }
  r.serveWave = wave;
  while (r.head < q.length && q[r.head].removed) r.head += 1;
  if (r.head > 32 && r.head * 2 >= q.length) {
    r.queue = q.slice(r.head);
    r.head = 0;
  }
}

