cat > /tmp/verify.mjs <<'EOF'
import { createGate } from '/mnt/c/claude_gsb/cla10/solverA/task014/src/index.js';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
let pass = 0, fail = 0;
const check = (name, cond) => { cond ? pass++ : (fail++, console.log('FAIL:', name)); };

// 1. Cancel head single -> later single flows in the SAME cut
{
  const root = createGate({ limit: 3, windowMs: 10000, maxWaitMs: 5000 });
  await root.acquire(2);
  const ac = new AbortController();
  const pHead = root.acquire(2, ac.signal).catch(e=>e.code);
  let late = false;
  const pLate = root.acquire(1).then(()=>{late=true;});
  await sleep(5);
  check('1a late waits behind head', !late);
  ac.abort();
  await sleep(5);
  check('1b late flows immediately after head cancel', late);
  check('1c head cancelled', (await pHead) === 'CANCELLED');
  await pLate;
}

// 2. Expire head single -> later flows; expiry beats cancel
{
  const root = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 30 });
  await root.acquire(1);
  const ac = new AbortController();
  const pHead = root.acquire(1, ac.signal).catch(e=>e.code);
  let late = false;
  const pLate = root.acquire(1).then(()=>{late=true;});
  await sleep(50);
  check('2a head expired', (await pHead) === 'WAIT_EXPIRED');
  check('2b late flows after head expiry', late);
  ac.abort(); // after settle: no-op
  await pLate;
}

// 3. Reparent migrated fitting combo: re-gathers, NOT granted early, grants at new flip
{
  const oldRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const newRoot = createGate({ limit: 5, window: 60, windowMs: 60, maxWaitMs: 5000 });
  await oldRoot.acquire(4);
  oldRoot.acquire(2).catch(()=>{});
  const pCombo = oldRoot.acquireAll([{ gate: a, units: 1 }]);
  a.reparent(newRoot);
  let done = false;
  pCombo.then(()=>{done=true;}).catch(e=>{done='err:'+e.code;});
  await sleep(5);
  check('3a migrated combo not granted early by adjustment', !done);
  await sleep(70);
  check('3b migrated combo granted at new family flip', done === true);
  check('3c a.inFlight 1', a.stats().inFlight === 1);
}

// 4. Migrated combo that cannot gather in new family waits for next flip, then grants
{
  const oldRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const newRoot = createGate({ limit: 5, windowMs: 60, maxWaitMs: 5000 });
  await oldRoot.acquire(4);
  oldRoot.acquire(2).catch(()=>{});
  const pCombo = oldRoot.acquireAll([{ gate: a, units: 2 }]); // gathers old (own2=4+... actually 4+2>5 no)
  // 4+ own? a.own headroom 2 => gathers 2 own, poolUsed=6>5 fails => rolls back, queues no hold
  a.reparent(newRoot); // newRoot: pool 0/5 -> regathers own 2, holds
  await sleep(70);
  let code = 'ok';
  const h = await pCombo.catch(e=>{code=e.code; return null;});
  check('4 migrated 2-unit combo grants in empty new family', code === 'ok' && a.stats().inFlight === 2);
  if (h) h.release();
}

// 5. updateMaxWaitMs follows owned entry into joined family
{
  const oldRoot = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 1, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const newRoot = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000 });
  await oldRoot.acquire(1);
  const p = a.acquire(1).catch(e=>e.code);
  a.reparent(newRoot);
  a.updateMaxWaitMs(0);
  await sleep(5);
  check('5 cross-family updateMaxWaitMs expires owned waiter', await p === 'WAIT_EXPIRED');
}

// 6. Pool shrink of joined family refuses migrated oversized owner entry
{
  const oldRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const newRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  await oldRoot.acquire(3);
  oldRoot.acquire(3).catch(()=>{});
  const p = a.acquire(3).catch(e=>e.code);
  a.reparent(newRoot);
  newRoot.updateLimit(2); // child a limit 2 <= 2; request 3 > pool 2 -> refuse
  await sleep(5);
  check('6 joined-family pool shrink refuses migrated entry', await p === 'QUOTA_EXCEEDED');
  check('6b counter on owner gate', a.stats().refused === 1);
  check('6c waiting zeroed', a.stats().waiting === 0);
}

// 7. Straddler refused; owner (oldRoot) counter, member charges zero in one snapshot
{
  const oldRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  const a = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const b = createGate({ limit: 2, windowMs: 10000, maxWaitMs: 5000, parent: oldRoot });
  const newRoot = createGate({ limit: 5, windowMs: 10000, maxWaitMs: 5000 });
  await oldRoot.acquire(3);
  oldRoot.acquire(3).catch(()=>{});
  const pCombo = oldRoot.acquireAll([{gate:a,units:1},{gate:b,units:1}]).catch(e=>e.code);
  a.reparent(newRoot);
  await sleep(5);
  check('7a straddler refused', await pCombo === 'QUOTA_EXCEEDED');
  check('7b owner refused counter', oldRoot.stats().refused === 1);
  check('7c member a waiting zeroed', a.stats().waiting === 0 && b.stats().waiting === 1);
  check('7d member a reserved zeroed', a.stats().reserved === 0);
}

// 8. New family pool cannot cover subtree -> throws QUOTA_EXCEEDED, everything unchanged
{
  const oldRoot = createGate({ limit: 3, windowMs: 10000 });
  const a = createGate({ limit: 2, windowMs: 10000, parent: oldRoot });
  const newRoot = createGate({ limit: 2, windowMs: 10000 });
  await a.acquire(2);
  await newRoot.acquire(1);
  let threw = null;
  try { a.reparent(newRoot); } catch(e){ threw = e.code; }
  check('8a reparent throws QUOTA_EXCEEDED', threw === 'QUOTA_EXCEEDED');
  check('8b old family unchanged (still full)', oldRoot.stats().inFlight === 0);
  await assertReject(oldRoot.acquire(2));
  async function assertReject(p){ try{ await p; check('8c old pool still charged', false);}catch(e){ check('8c old pool still charged by subtree', e.code==='QUOTA_EXCEEDED');} }
}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
