import { createGate } from '/mnt/c/claude_gsb/cla10/solverA/task014/src/index.js';
const sleep = (ms) => new Promise(r=>setTimeout(r,ms));

let rejected = 0, unhandled = 0;
process.on('unhandledRejection', () => { unhandled++; });

function mkGate(limit, parent, wm=20, wait=200){
  return createGate({limit, windowMs: wm, maxWaitMs: wait, ...(parent?{parent}:{})});
}

async function scenario(seed){
  let s = seed;
  const rnd = () => (s = (s*1103515245+12345)&0x7fffffff)/0x7fffffff;
  const root = mkGate(6, null, 15, 300);
  const kids = [mkGate(4, root, 30, 300), mkGate(3, root, 25, 300), mkGate(2, root, 40, 300)];
  const all = [root, ...kids];
  const pend = [];
  const handles = [];
  for (let i=0;i<400;i++){
    const g = all[Math.floor(rnd()*all.length)];
    const roll = rnd();
    try {
      if (roll < 0.45) {
        const u = 1 + Math.floor(rnd()*4);
        const ac = new AbortController();
        const p = (rnd()<0.5?g.acquire(u, ac.signal):g.acquireAll([{gate:g,units:u}], ac.signal))
          .then(h=>{handles.push(h);}, e=>{rejected++;});
        pend.push({p, ac});
      } else if (roll < 0.55 && pend.length) {
        pend[Math.floor(rnd()*pend.length)].ac.abort();
      } else if (roll < 0.62) {
        try { kids[Math.floor(rnd()*kids.length)].reparent(all[Math.floor(rnd()*all.length)]); } catch {}
      } else if (roll < 0.7) {
        try { g.updateLimit(1+Math.floor(rnd()*8)); } catch {}
      } else if (roll < 0.78 && handles.length) {
        const h = handles.pop(); h.release();
      }
    } catch(e){ /* param errors expected */ }
    if (i % 7 === 0) await sleep(5);
  }
  await sleep(350);
  for (const h of handles) { try{h.release();}catch{} }
  // Invariants
  let ok = true;
  for (const g of all) {
    const st = g.stats();
    if (st.waiting < 0 || st.reserved < 0 || st.inFlight < 0) ok = false;
    if (Math.abs(st.inFlight % 1) > 0) ok = false;
  }
  return ok;
}

let allOk = true;
for (let seed=1; seed<=8; seed++){
  const ok = await scenario(seed*7919);
  if (!ok) { console.log('invariant violated seed', seed); allOk=false; }
}
await sleep(50);
console.log('rejected:', rejected, 'unhandled:', unhandled, 'invariants:', allOk?'OK':'BROKEN');
process.exit((unhandled===0 && allOk)?0:1);
