cat > /tmp/verify4.mjs <<'EOF'
import { createGate } from '/mnt/c/claude_gsb/cla10/solverA/task014/src/index.js';
const sleep = (ms) => new Promise(r=>setTimeout(r,ms));
let pass=0,fail=0; const check=(n,c)=>{c?pass++:(fail++,console.log('FAIL:',n));};

// Whole combo migrates: waiting stays on (moved) member gate, reservation is
// re-taken in the joined family; both zero in one snapshot when it grants.
{
  const oldRoot = createGate({limit:5, windowMs:10000, maxWaitMs:5000});
  const a = createGate({limit:2, windowMs:10000, maxWaitMs:5000, parent:oldRoot});
  const newRoot = createGate({limit:5, windowMs:40, maxWaitMs:5000});
  await oldRoot.acquire(4);
  oldRoot.acquire(2).catch(()=>{}); // earlier blocker
  const p = oldRoot.acquireAll([{gate:a,units:2}]); // gathers a.own 2, queued
  check('pre: a.waiting 2', a.stats().waiting===2);
  check('pre: a.reserved 2', a.stats().reserved===2);
  a.reparent(newRoot); // whole combo moves; re-gathers in empty new family
  check('post-reparent a.waiting stays 2', a.stats().waiting===2);
  check('post-reparent a.reserved re-taken 2', a.stats().reserved===2);
  check('post-reparent not granted early', a.stats().inFlight===0);
  const h = await p; // grants at new flip
  check('grant: inFlight 2', a.stats().inFlight===2);
  check('grant: waiting 0', a.stats().waiting===0);
  check('grant: reserved 0', a.stats().reserved===0);
  h.release();
}

// Failed gather while queuing moves ONLY rolledBack (no other counter cut).
{
  const root = createGate({limit:3, windowMs:10000, maxWaitMs:5000});
  const a = createGate({limit:3, windowMs:10000, maxWaitMs:5000, parent:root});
  await root.acquire(3);
  const before = {granted:1, refused:0, expired:0, cancelled:0};
  const p = root.acquireAll([{gate:a,units:2}]).catch(e=>e.code); // can't gather
  const s = root.stats();
  check('rolledBack moved once', s.rolledBack===1);
  check('no refused/expired/cancelled', s.refused===0&&s.expired===0&&s.cancelled===0);
  check('granted unchanged', s.granted===1);
  p.then(()=>{});
  await sleep(50); // flip: gathers and grants
  check('granted after flip', root.stats().granted===2 && root.stats().rolledBack===2);
}
console.log(`${pass} passed, ${fail} failed`);
process.exit(fail?1:0);
EOF
